const sid = (msg._session && msg._session.id) || 'x';
const bufs = context.get('bufs') || {};
bufs[sid] = (bufs[sid] || '') + msg.payload.toString();
if (bufs[sid].indexOf('\n') < 0) { context.set('bufs', bufs); return null; }
const line = bufs[sid].split('\n')[0];
delete bufs[sid];
context.set('bufs', bufs);
let c;
try { c = JSON.parse(line); } catch (e) {
  msg.payload = JSON.stringify({ success: false, devices: {}, message: 'JSON tidak valid' }) + '\n';
  return [null, msg];
}
msg.command = c;
msg.payload = { roomCode: c.roomCode, classKey: c.classKey, action: c.action, eventId: c.eventId, bookingId: c.bookingId, source: c.source };
return [msg, null];

// WAJIB: msg._session tidak boleh hilang di alur kontrol, dan isi msg.ack = { success, devices:{ac,lamp,door}, message }
const ack = msg.ack || { success: false, devices: {}, message: 'tidak ada hasil kontrol' };
msg.payload = JSON.stringify({ success: !!ack.success, devices: ack.devices || {}, message: ack.message || '' }) + '\n';
return msg;
